<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Expense Tracker</title>
<style>
  * { box-sizing: border-box; }
  body { font-family: system-ui, sans-serif; margin: 0; padding: 1rem; background: #f4f5f7; color: #222; }
  h1 { font-size: 1.4rem; }
  .card { background: #fff; border-radius: 8px; padding: 1rem; margin-bottom: 1rem; box-shadow: 0 1px 3px rgba(0,0,0,.1); }
  label { display: block; font-size: .8rem; margin-bottom: .2rem; font-weight: 600; }
  input, select { width: 100%; padding: .5rem; border: 1px solid #ccc; border-radius: 4px; font-size: 1rem; }
  .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: .75rem; }
  button { cursor: pointer; border: none; border-radius: 4px; padding: .5rem .9rem; font-size: 1rem; }
  #add-expense { background: #2d6cdf; color: #fff; margin-top: .75rem; }
  #form-error { color: #c0392b; font-weight: 600; margin-top: .5rem; min-height: 1.2em; }
  table { width: 100%; border-collapse: collapse; }
  th, td { text-align: left; padding: .5rem; border-bottom: 1px solid #eee; }
  .exp-del { background: #c0392b; color: #fff; padding: .3rem .6rem; }
  .summary { display: flex; flex-wrap: wrap; gap: .75rem; }
  .cat-total { background: #eef2fb; padding: .4rem .7rem; border-radius: 4px; font-size: .9rem; }
  #total { font-size: 1.3rem; font-weight: 700; }
  .amt { font-variant-numeric: tabular-nums; }
</style>
</head>
<body>
<h1>Personal Expense Tracker</h1>

<div class="card">
  <h2 style="margin-top:0;font-size:1.1rem;">Add Expense</h2>
  <div class="grid">
    <div>
      <label for="amount">Amount</label>
      <input type="number" id="amount" step="0.01" placeholder="0.00">
    </div>
    <div>
      <label for="category">Category</label>
      <select id="category">
        <option value="groceries">groceries</option>
        <option value="transport">transport</option>
        <option value="bills">bills</option>
        <option value="fun">fun</option>
      </select>
    </div>
    <div>
      <label for="date">Date</label>
      <input type="date" id="date">
    </div>
    <div>
      <label for="note">Note (optional)</label>
      <input type="text" id="note" placeholder="e.g. weekly shop">
    </div>
  </div>
  <button id="add-expense" type="button">Add Expense</button>
  <div id="form-error"></div>
</div>

<div class="card">
  <h2 style="margin-top:0;font-size:1.1rem;">Filters</h2>
  <div class="grid">
    <div>
      <label for="filter-category">Category</label>
      <select id="filter-category">
        <option value="all">all</option>
        <option value="groceries">groceries</option>
        <option value="transport">transport</option>
        <option value="bills">bills</option>
        <option value="fun">fun</option>
      </select>
    </div>
    <div>
      <label for="filter-from">From</label>
      <input type="date" id="filter-from">
    </div>
    <div>
      <label for="filter-to">To</label>
      <input type="date" id="filter-to">
    </div>
  </div>
</div>

<div class="card">
  <h2 style="margin-top:0;font-size:1.1rem;">Summary</h2>
  <p>Total (visible): <span id="total">0.00</span></p>
  <div class="summary" id="cat-summary">
    <span class="cat-total" data-cat="groceries">groceries: 0.00</span>
    <span class="cat-total" data-cat="transport">transport: 0.00</span>
    <span class="cat-total" data-cat="bills">bills: 0.00</span>
    <span class="cat-total" data-cat="fun">fun: 0.00</span>
  </div>
</div>

<div class="card">
  <table>
    <thead>
      <tr><th>Amount</th><th>Category</th><th>Date</th><th>Note</th><th></th></tr>
    </thead>
    <tbody id="expense-list"></tbody>
  </table>
</div>

<script>
(function(){
  const CATEGORIES = ['groceries','transport','bills','fun'];
  const KEY = 'expense-tracker-data';
  let expenses = [];

  function load(){
    try { expenses = JSON.parse(localStorage.getItem(KEY)) || []; }
    catch(e){ expenses = []; }
    if(!Array.isArray(expenses)) expenses = [];
  }
  function save(){ localStorage.setItem(KEY, JSON.stringify(expenses)); }

  const amountEl = document.getElementById('amount');
  const categoryEl = document.getElementById('category');
  const dateEl = document.getElementById('date');
  const noteEl = document.getElementById('note');
  const addBtn = document.getElementById('add-expense');
  const errorEl = document.getElementById('form-error');
  const listEl = document.getElementById('expense-list');
  const totalEl = document.getElementById('total');
  const fCat = document.getElementById('filter-category');
  const fFrom = document.getElementById('filter-from');
  const fTo = document.getElementById('filter-to');

  function isVisible(exp){
    if(fCat.value !== 'all' && exp.category !== fCat.value) return false;
    if(fFrom.value && exp.date < fFrom.value) return false;
    if(fTo.value && exp.date > fTo.value) return false;
    return true;
  }

  function render(){
    // newest first: sort by createdAt descending
    const sorted = expenses.slice().sort((a,b)=> b.createdAt - a.createdAt);
    listEl.innerHTML = '';
    let total = 0;
    const catTotals = {};
    CATEGORIES.forEach(c => catTotals[c] = 0);

    sorted.forEach(exp => {
      if(!isVisible(exp)) return;
      total += exp.amount;
      if(catTotals[exp.category] !== undefined) catTotals[exp.category] += exp.amount;

      const tr = document.createElement('tr');
      tr.className = 'expense';
      tr.dataset.id = exp.id;

      const tdAmt = document.createElement('td');
      tdAmt.className = 'amt';
      tdAmt.textContent = exp.amount.toFixed(2);
      const tdCat = document.createElement('td');
      tdCat.textContent = exp.category;
      const tdDate = document.createElement('td');
      tdDate.textContent = exp.date;
      const tdNote = document.createElement('td');
      tdNote.textContent = exp.note || '';
      const tdDel = document.createElement('td');
      const del = document.createElement('button');
      del.className = 'exp-del';
      del.type = 'button';
      del.textContent = 'Delete';
      del.addEventListener('click', () => removeExpense(exp.id));
      tdDel.appendChild(del);

      tr.append(tdAmt, tdCat, tdDate, tdNote, tdDel);
      listEl.appendChild(tr);
    });

    totalEl.textContent = total.toFixed(2);
    CATEGORIES.forEach(c => {
      const el = document.querySelector('.cat-total[data-cat="'+c+'"]');
      if(el) el.textContent = c + ': ' + catTotals[c].toFixed(2);
    });
  }

  function removeExpense(id){
    expenses = expenses.filter(e => e.id !== id);
    save();
    render();
  }

  function addExpense(){
    errorEl.textContent = '';
    const raw = amountEl.value.trim();
    const amount = Number(raw);
    if(raw === '' || isNaN(amount) || amount <= 0){
      errorEl.textContent = 'Please enter a valid amount greater than zero.';
      return;
    }
    if(!dateEl.value){
      errorEl.textContent = 'Please choose a date.';
      return;
    }
    const exp = {
      id: (Date.now().toString(36) + Math.random().toString(36).slice(2)),
      amount: amount,
      category: categoryEl.value,
      date: dateEl.value,
      note: noteEl.value.trim(),
      createdAt: Date.now()
    };
    expenses.push(exp);
    save();
    errorEl.textContent = '';
    amountEl.value = '';
    noteEl.value = '';
    render();
  }

  addBtn.addEventListener('click', addExpense);
  fCat.addEventListener('change', render);
  fFrom.addEventListener('change', render);
  fTo.addEventListener('change', render);

  // default date to today for convenience
  (function(){
    const t = new Date();
    const iso = t.getFullYear() + '-' + String(t.getMonth()+1).padStart(2,'0') + '-' + String(t.getDate()).padStart(2,'0');
    dateEl.value = iso;
  })();

  load();
  render();
})();
</script>
</body>
</html>
